class TestCrossModelIntegration:
    """Tests that verify interactions between models."""

    def test_full_key_exchange_flow(self, valid_public_key, valid_private_key):
        """Should simulate full key generation and exchange flow."""
        # Generate key pair
        key_pair = KeyPairResponse(
            public_key=valid_public_key,
            private_key=valid_private_key,
        )

        # Initiate exchange
        exchange_request = KeyExchangeRequest(
            recipient_public_key=key_pair.public_key,
            sender_ephemeral_public_key=valid_public_key,
        )

        # Complete exchange
        exchange_response = KeyExchangeResponse(
            shared_secret="ZGVyaXZlZC1zZWNyZXQ=",
            key_id=key_pair.public_key.key_id,
        )

        # Verify chain integrity
        assert exchange_request.recipient_public_key == key_pair.public_key
        assert exchange_response.key_id == key_pair.public_key.key_id

    def test_model_dump_modes(self, valid_key_pair_response):
        """Should support both python and json dump modes."""
        python_dump = valid_key_pair_response.model_dump(mode="python")
        json_dump = valid_key_pair_response.model_dump(mode="json")

        assert isinstance(python_dump["timestamp"], datetime)
        assert isinstance(json_dump["timestamp"], str)

    def test_model_copy(self, valid_key_pair_response):
        """Should support deep copy without shared references."""
        copied = valid_key_pair_response.model_copy(deep=True)
        assert copied == valid_key_pair_response
        assert copied is not valid_key_pair_response
        assert copied.public_key is not valid_key_pair_response.public_key

    def test_equality_semantics(self, valid_public_key_data):
        """Should treat equal models as equal."""
        key1 = KyberPublicKey(**valid_public_key_data)
        key2 = KyberPublicKey(**valid_public_key_data)
        assert key1 == key2
        assert hash(key1) == hash(key2)

    def test_inequality_semantics(self, valid_public_key_data):
        """Should treat different models as unequal."""
        key1 = KyberPublicKey(**valid_public_key_data)
        data = valid_public_key_data.copy()
        data["key_id"] = "different-id"
        key2 = KyberPublicKey(**data)
        assert key1 != key2


