class TestEdgeCases:
    """Tests for unusual or adversarial inputs."""

    @pytest.mark.parametrize("field_name", [
        "key_id",
        "public_key_bytes",
        "private_key_bytes",
        "shared_secret",
    ])
    def test_unicode_strings(self, field_name):
        """Should accept unicode strings in string fields."""
        data = {
            "key_id": "🔑-001",
            "public_key_bytes": "c2FtcGxl",
            "private_key_bytes": "c2FtcGxl",
            "shared_secret": "c2VjcmV0",
        }
        data[field_name] = "ünïcödé-🔐"
        if field_name == "key_id":
            model = KyberPublicKey(**data)
            assert model.key_id == "ünïcödé-🔐"
        elif field_name == "public_key_bytes":
            model = KyberPublicKey(**data)
            assert model.public_key_bytes == "ünïcödé-🔐"
        elif field_name == "private_key_bytes":
            model = KyberPrivateKey(**data)
            assert model.private_key_bytes == "ünïcödé-🔐"
        else:
            model = KeyExchangeResponse(**data)
            assert model.shared_secret == "ünïcödé-🔐"

    @pytest.mark.parametrize("model_class,data", [
        (KyberPublicKey, {"key_id": None, "public_key_bytes": "x"}),
        (KyberPrivateKey, {"key_id": "x", "private_key_bytes": None}),
        (KeyExchangeResponse, {"shared_secret": None, "key_id": "x"}),
    ])
    def test_none_values_rejected(self, model_class, data):
        """Should reject None for required string fields."""
        with pytest.raises(ValidationError):
            model_class(**data)

    def test_very_long_strings(self):
        """Should handle very long strings without error."""
        long_string = "A" * 1000000  # 1MB string
        key = KyberPublicKey(key_id=long_string, public_key_bytes=long_string)
        assert len(key.key_id) == 1000000
        assert len(key.public_key_bytes) == 1000000

    def test_nested_model_validation_error_message(self, valid_public_key):
        """Should provide clear error messages for nested validation failures."""
        with pytest.raises(ValidationError) as exc_info:
            KeyExchangeRequest(
                recipient_public_key=KyberPublicKey(
                    key_id="", public_key_bytes=""  # valid but empty
                ),
                sender_ephemeral_public_key=valid_public_key,
            )
        # Should not raise because empty strings are allowed
        # This test verifies that empty strings don't trigger validation errors

    def test_invalid_base64_content(self):
        """Should NOT validate base64 content (no validator defined)."""
        # This is a contract test: the model does not enforce base64 validity
        key = KyberPublicKey(
            key_id="pk-invalid",
            public_key_bytes="!!!not-base64!!!",
        )
        assert key.public_key_bytes == "!!!not-base64!!!"


